sandbox.code:
interface User { id: number; name: string; }

const inline: { id: number; name: string } = { id: 1, name: 'Ada' };
const named: User = { id: 2, name: 'Linus' };

console.log(inline.name, named.name);
console.log(inline.id + named.id);

function greet(p: { name: string }): string {
  return 'Hello, ' + p.name;
}

const dog = { name: 'Rex', legs: 4, bark: () => 'woof' };
// dog has more than greet needs, but it has a name
console.log(greet(dog));
console.log(greet({ name: 'Ada' }));

