solution.code:
interface Order {
  id: number;
  customer: { name: string; email: string };
  total: number;
}

const order: Order = {
  id: 101,
  customer: { name: 'Ada', email: 'ada@example.com' },
  total: 49.99
};

console.log(order.customer.name, order.total);

