solution.code:
interface User { id: number; name: string; }

const u: User = { id: 1, name: 'Ada' };

console.log('Hello, ' + u.name); // 'Hello, Ada'

function formatUser(user: { id: number; name: string; email?: string }): string {
  const contact = user.email ? ` <${user.email}>` : '';
  return `#${user.id} ${user.name}${contact}`;
}

console.log(formatUser({ id: 1, name: 'Ada', email: 'ada@x.com' }));
console.log(formatUser({ id: 2, name: 'Linus' }));
